#!/bin/sh
# Who Watches the Road: build the civic transparency site into a site home.
#
#   build.sh --home DIR --obs DIR [--observe] [--site NAME] [--host HOST]
#            [--web BIN] [--ledger BIN] [--project BIN] [--port N]
#
# --observe  read the sources again through ForeignTwin (`bonfyre-project
#            foreign observe`: robots preflight, retained bytes, receipt).
#            Without it, pages are rebuilt from the receipts already in --obs.
# Pages are generated by civic-ledger (cmd/BonfyreSourceFrontier) from those
# receipts and written with the documented `bonfyre-web-address site` verbs.
# It publishes nothing: the site lives in --home until someone places it.
set -eu
HERE=$(cd "$(dirname "$0")" && pwd)
ROOT=$(cd "$HERE/../../.." && pwd)
HOME_DIR= OBS= OBSERVE=0 SITE=civic-watch HOST=watch.example.test PORT=28977
WEB=${BONFYRE_TEST_WEB_BINARY:-$ROOT/cmd/BonfyreWebAddress/bonfyre-web-address}
LEDGER=$ROOT/cmd/BonfyreSourceFrontier/tools/civic-ledger
PROJECT=${BONFYRE_PROJECT_BIN:-$HOME/.bonfyre/bin/bonfyre-project}
while [ $# -gt 0 ]; do
  case $1 in
    --home) HOME_DIR=$2; shift ;; --obs) OBS=$2; shift ;; --observe) OBSERVE=1 ;;
    --site) SITE=$2; shift ;; --host) HOST=$2; shift ;; --port) PORT=$2; shift ;;
    --web) WEB=$2; shift ;; --ledger) LEDGER=$2; shift ;; --project) PROJECT=$2; shift ;;
    *) echo "build.sh: unknown argument $1" >&2; exit 2 ;;
  esac; shift
done
[ -n "$HOME_DIR" ] && [ -n "$OBS" ] || { sed -n '4,5p' "$0" >&2; exit 2; }
mkdir -p "$HOME_DIR" "$OBS"

# Council agenda services (Legistar clients) and the places they belong to.
COUNCILS="Dallas:cityofdallas Fort_Worth:fortworthgov McKinney:mckinney Plano:plano Arlington:arlingtontx Irving:irving Garland:garland Frisco:frisco Denton:denton"
LEGISTAR_FILTER='%24filter=substringof(%27Flock%27%2CMatterTitle)%20or%20substringof(%27license%20plate%27%2CMatterTitle)'
# Counts only: Overpass returns one total per town and county, never a position.
OVERPASS_QUERY='[out:json][timeout:90];area["name"="Texas"]["admin_level"="4"]->.tx;(rel(area.tx)["admin_level"="6"]["name"~"^(Dallas|Tarrant|Collin|Denton) County$"];)->.counties;foreach.counties->.k(.k map_to_area->.ka;rel(area.ka)["admin_level"="8"]["boundary"="administrative"];map_to_area->.cities;foreach.cities->.c(node(area.c)["surveillance:type"="ALPR"];make city county=k.u(t["name"]),name=c.u(t["name"]),cameras=count(nodes);out;);node(area.ka)["surveillance:type"="ALPR"]->.all;make county name=k.u(t["name"]),cameras=all.count(nodes);out;);'
OVERPASS_HOST=maps.mail.ru/osm/tools/overpass   # overpass-api.de disallows /api/ in robots

usable() { [ -f "$1" ] && [ "$(jq -r '.policy_decision + ":" + (.http_status|tostring)' "$1")" = "allow:200" ]; }
observe() { # twin url name -- a failed read never replaces the last usable one
  rm -f "$OBS/$3.next.receipt.json" "$OBS/$3.next.body"
  "$PROJECT" foreign observe "$1" "$2" --receipt "$OBS/$3.next.receipt.json" --body "$OBS/$3.next.body" >/dev/null 2>&1 || true
  [ -f "$OBS/$3.next.receipt.json" ] || { echo "build.sh: no receipt for $3" >&2; exit 1; }
  if usable "$OBS/$3.next.receipt.json" || ! usable "$OBS/$3.receipt.json"; then
    jq -c --arg b "$3.body" '.body_path=$b' "$OBS/$3.next.receipt.json" > "$OBS/$3.receipt.json"
    if [ -f "$OBS/$3.next.body" ]; then mv -f "$OBS/$3.next.body" "$OBS/$3.body"; else rm -f "$OBS/$3.body"; fi
  else
    echo "build.sh: $3 read failed ($(jq -r .http_status "$OBS/$3.next.receipt.json")); keeping the read of $(jq -r .observed_at "$OBS/$3.receipt.json")" >&2
  fi
  rm -f "$OBS/$3.next.receipt.json" "$OBS/$3.next.body"
}
if [ "$OBSERVE" = 1 ]; then
  q=$(printf '%s' "$OVERPASS_QUERY" | jq -sRr @uri)
  observe civic-osm-alpr-north-texas-counts "https://$OVERPASS_HOST/api/interpreter?data=$q" towns
  for pair in $COUNCILS; do
    client=${pair#*:}
    observe "civic-legistar-$client-readers" "https://webapi.legistar.com/v1/$client/matters?$LEGISTAR_FILTER" "council-$client"
  done
fi

WORK=$(mktemp -d "${TMPDIR:-/tmp}/civic-build.XXXXXX"); trap 'rm -rf "$WORK"' 0 1 2 15
"$LEDGER" towns "$OBS/towns.receipt.json" > "$WORK/towns.md"
cp "$HERE/pages/council-head.md" "$WORK/council.md"
reads="Town counts from OpenStreetMap=$OBS/towns.receipt.json"
for pair in $COUNCILS; do
  place=$(printf '%s' "${pair%%:*}" | tr _ ' '); client=${pair#*:}; r="$OBS/council-$client.receipt.json"
  [ -f "$r" ] || continue
  reads="$reads
$place council agendas=$r"
  # A place whose service answered is listed even when it holds nothing on readers;
  # a place whose read failed is left to the reads table on the sources page.
  if "$LEDGER" council "$place" "$client.legistar.com" "$r" > "$WORK/one.md" 2>/dev/null; then cat "$WORK/one.md" >> "$WORK/council.md"; fi
done
cat "$HERE/pages/council-foot.md" >> "$WORK/council.md"
cp "$HERE/pages/sources.md" "$WORK/sources.md"
printf '\n' >> "$WORK/sources.md"
printf '%s\n' "$reads" | tr '\n' '\0' | xargs -0 "$LEDGER" reads >> "$WORK/sources.md"

s() { "$WEB" site "$@" --home "$HOME_DIR"; }
if ! s show "$SITE" --json >/dev/null 2>&1; then
  s new "$SITE" --title "Who Watches the Road" --tagline "License plate readers in North Texas, from the public record" \
    --accent "#f2c230" --host "$HOST" --port "$PORT" --no-open >/dev/null
fi
s set "$SITE" --presentation "$ROOT/docs/experiences/presentations/civic-watch.json" >/dev/null
s set "$SITE" --footnote "Built from public records. Map data from OpenStreetMap contributors (ODbL)." \
  --footnote-label "Where this comes from" --footnote-link "https://$HOST/sources" >/dev/null
page() { s page "$SITE" --route "$1" --replace --title "$2" --file "$3" >/dev/null; }
page /cameras "Cameras" "$WORK/towns.md"
page /council-votes "Council votes" "$WORK/council.md"
page /ask "Ask your city" "$HERE/pages/ask.md"
page /search-logs "Search logs" "$HERE/pages/search-logs.md"
page /sources "Sources" "$WORK/sources.md"
page /fix "Fix something" "$HERE/pages/fix.md"
# Routes from an earlier build under longer names give way to these.
for old in /cameras-by-town /what-councils-voted-on /ask-your-city /reading-a-search-log /where-this-comes-from /fix-something; do
  s page "$SITE" --route "$old" --remove >/dev/null 2>&1 || true
done

# The kit's starter post gives way to the site's own; posts are its dated changes.
db="$HOME_DIR/cms.db"
for id in $(sqlite3 -readonly "$db" "select id from community_post where title='This site is live' and status!='withdrawn'" 2>/dev/null); do
  s post "$SITE" --withdraw "$id" >/dev/null
done
if [ -z "$(sqlite3 -readonly "$db" "select id from community_post where title='What this site holds' and status!='withdrawn' limit 1" 2>/dev/null)" ]; then
  s post "$SITE" --title "What this site holds" --file "$HERE/pages/welcome.md" >/dev/null
fi
echo "built $SITE in $HOME_DIR from $(printf '%s\n' "$reads" | wc -l | tr -d ' ') reads"
